#!/bin/bash
# 40-draw inner CV at an arbitrary training size. MEDMNIST_N is the sweep variable.
#   MEDMNIST_SWEEP_N=50 bash run_draws_n.sh
# Both arms selected identically (spectral family from the property rule, spatial over
# {4,7,14}); draws are seeds 105-144, disjoint from the reporting draws 5-104.
# Job list lives in results/, NOT the session scratchpad -- that gets wiped on restart.
# Do not edit this file while it runs: bash re-reads a running script by byte offset.
set -u
N=${MEDMNIST_SWEEP_N:?set MEDMNIST_SWEEP_N}
PY=/opt/dpeekenv/bin/python
OUT=/workspace/results/medmnist_cvdraws_n$N
TSV=/workspace/results/draws_all_jobs.tsv
PAR=${PAR:-6}
sem(){ while [ "$(jobs -rp|wc -l)" -ge "$PAR" ]; do wait -n; done; }
echo "=== n=$N start $(date +%H:%M:%S)"
for blk in $(seq 0 7); do
  s0=$((105 + blk*5))
  while IFS=$'\t' read -r ds p cfg e npz; do
    o=$OUT/$ds/$cfg/d$s0
    [ -f "$o/medmnist_cv.csv" ] && continue
    sem; mkdir -p "$o"
    env $e MEDMNIST_CV_SEED0=$s0 MEDMNIST_SEEDS=5 MEDMNIST_CVK=5 MEDMNIST_N=$N \
        MEDMNIST_CVSEED=0 MEDMNIST_PATCH=$p MEDMNIST_ARM=$cfg \
        MEDMNIST_NPZ=$npz MEDMNIST_OUT=$o \
        $PY medmnist_cv.py > "$o/log.txt" 2>&1 &
  done < $TSV
  for ds in organmnist3d nodulemnist3d adrenalmnist3d fracturemnist3d vesselmnist3d synapsemnist3d; do
    npz=/workspace/data/medmnist/$ds.npz
    [ "$ds" = organmnist3d ] && npz=/agent-home/medmnist/organmnist3d.npz
    for p in 4 7 14; do
      o=$OUT/$ds/spatial_p$p/d$s0
      [ -f "$o/medmnist_cv.csv" ] && continue
      sem; mkdir -p "$o"
      env MEDMNIST_CV_ARM=spatial MEDMNIST_CV_SEED0=$s0 MEDMNIST_SEEDS=5 MEDMNIST_CVK=5 \
          MEDMNIST_N=$N MEDMNIST_CVSEED=0 MEDMNIST_PATCH=$p MEDMNIST_ARM=spatial_p$p \
          MEDMNIST_NPZ=$npz MEDMNIST_OUT=$o \
          $PY medmnist_cv.py > "$o/log.txt" 2>&1 &
    done
  done
  echo "n=$N block $blk (draws $s0-$((s0+4))) dispatched $(date +%H:%M:%S)"
done
wait
echo "=== n=$N done $(date +%H:%M:%S)"
